package site

import (
	"fmt"
	"html"
	"regexp"
	"strings"
	"unicode/utf8"
)

// generatedHeader marks every rendered file. A generated file is never edited
// by hand; the header names the source and the command.
const generatedHeader = "<!-- Generated by cmd/gensite from docs/site.json. DO NOT EDIT. -->"

// markdownTokenRE keeps a link or a code span together while wrapping. A link
// may contain spaces, so a plain strings.Fields split would break it.
var markdownTokenRE = regexp.MustCompile("\\[[^\\]]*\\]\\([^)]*\\)[.,;:!?)]*|`[^`]*`[.,;:!?)]*|\\S+")

// markdownLinkRE is used only where Markdown text has to become HTML inside a
// generated section. The source is authored, and the href comes from the page
// table, so this is a formatting step, not an untrusted parser.
var markdownLinkRE = regexp.MustCompile(`\[([^\]]+)\]\(([^)]+)\)`)

var markdownCodeRE = regexp.MustCompile("`([^`]+)`")

// docLinks are the destinations inside docs/. A French page is a sibling under
// docs/fr/, so both trees link to the bare file name; a prefix of ../ would
// resolve to the English page one level up.
func (s Site) docLinks() map[string]string {
	out := map[string]string{}
	for _, page := range s.Pages() {
		if page.Nav {
			out[page.Key] = page.DocsName("en")
		}
	}
	return out
}

// readmeLinks are the destinations from the repository root.
func (s Site) readmeLinks(lang string) map[string]string {
	out := map[string]string{}
	for _, page := range s.Pages() {
		if page.Nav {
			out[page.Key] = page.File(lang)
		}
	}
	return out
}

// assetName resolves one generated asset from the page table. A consumer never
// types an asset file name.
func (s Site) assetName(key, lang string) string {
	for _, page := range s.Pages() {
		if page.Key == key {
			return pathBase(page.File(lang))
		}
	}
	return ""
}

func pathBase(name string) string {
	if index := strings.LastIndexByte(name, '/'); index >= 0 {
		return name[index+1:]
	}
	return name
}

// docAsset is the asset reference from a page under docs/.
func (s Site) docAsset(key, lang string) string {
	if lang == "fr" {
		return "../assets/" + s.assetName(key, lang)
	}
	return "assets/" + s.assetName(key, lang)
}

// readmeAsset is the asset reference from the repository root.
func (s Site) readmeAsset(key, lang string) string {
	return "docs/assets/" + s.assetName(key, lang)
}

// htmlHref turns a documentation link into the final HTML target for a raw
// HTML anchor. Jekyll's relative-links plugin rewrites Markdown links, not raw
// HTML, so the generated sections must name the built page directly.
func htmlHref(href string) string {
	if strings.HasPrefix(href, "http://") || strings.HasPrefix(href, "https://") ||
		strings.HasPrefix(href, "#") || strings.HasPrefix(href, "/") {
		return href
	}
	base, fragment := href, ""
	if index := strings.IndexByte(href, '#'); index >= 0 {
		base, fragment = href[:index], href[index:]
	}
	if strings.HasSuffix(base, ".md") {
		return strings.TrimSuffix(base, ".md") + ".html" + fragment
	}
	return href
}

// inlineHTML turns one authored paragraph into safe inline HTML. Placeholders
// are resolved first, then the small Markdown subset the source uses. The text
// is escaped before the two formatting rules run, so authored copy cannot
// inject markup.
func (s Site) inlineHTML(value, lang string) string {
	text := html.EscapeString(s.text(value, lang))
	text = markdownLinkRE.ReplaceAllStringFunc(text, func(match string) string {
		parts := markdownLinkRE.FindStringSubmatch(match)
		return `<a href="` + htmlHref(parts[2]) + `">` + parts[1] + `</a>`
	})
	text = markdownCodeRE.ReplaceAllString(text, `<code>$1</code>`)
	return text
}

// wrap folds one paragraph at width runes without splitting a link or a code
// span. It preserves no original line breaks: the source is one paragraph per
// value.
func wrap(text string, width int) string {
	tokens := markdownTokenRE.FindAllString(text, -1)
	var out strings.Builder
	line := 0
	for _, token := range tokens {
		size := utf8.RuneCountInString(token)
		switch {
		case line == 0:
			out.WriteString(token)
			line = size
		case line+1+size > width:
			out.WriteString("\n")
			out.WriteString(token)
			line = size
		default:
			out.WriteString(" ")
			out.WriteString(token)
			line += 1 + size
		}
	}
	return out.String()
}

// item renders a list item with a hanging indent.
func item(marker, text string, width int) string {
	body := wrap(text, width-utf8.RuneCountInString(marker))
	return marker + strings.Join(strings.Split(body, "\n"), "\n"+strings.Repeat(" ", utf8.RuneCountInString(marker)))
}

// paragraph appends a wrapped paragraph and one blank line.
func paragraph(out *strings.Builder, text string) {
	out.WriteString(wrap(text, 80))
	out.WriteString("\n\n")
}

// heading appends a level-two heading and one blank line.
func heading(out *strings.Builder, text string) {
	out.WriteString("## ")
	out.WriteString(text)
	out.WriteString("\n\n")
}

// Landing renders docs/index.md or docs/fr/index.md. The structure is HTML so
// the generated page can carry a real hero, cards and a boundary section. The
// navigation stays a Markdown paragraph so the same file reads correctly on
// GitHub and on the built site.
func (s Site) Landing(lang string) []byte {
	links := s.docLinks()
	title := s.Hero.Title.For(lang)
	if lang == "fr" {
		title += " (français)"
	}
	var out strings.Builder
	out.WriteString("---\n")
	out.WriteString("layout: default\n")
	fmt.Fprintf(&out, "title: %s\n", yamlQuote(title))
	fmt.Fprintf(&out, "lang: %s\n", yamlQuote(lang))
	// The head override reads this flag, so only the two landings carry the
	// alternate links and the automatic language switch.
	out.WriteString("language_switch: true\n")
	fmt.Fprintf(&out, "description: %s\n", yamlQuote(s.Hero.Promise.For(lang)))
	// The theme's head calls jekyll-seo-tag, which turns this image block into
	// the Open Graph and Twitter card. The path, size and alt text come from
	// the one media table, so the preview cannot drift from the committed PNG.
	out.WriteString("image:\n")
	fmt.Fprintf(&out, "  path: %s\n", yamlQuote("/"+strings.TrimPrefix(s.Media.SocialPreview, "docs/")))
	fmt.Fprintf(&out, "  width: %d\n", s.Media.SocialWidth)
	fmt.Fprintf(&out, "  height: %d\n", s.Media.SocialHeight)
	fmt.Fprintf(&out, "  alt: %s\n", yamlQuote(s.Product+": "+s.Hero.Banner.For(lang)))
	out.WriteString("---\n\n")

	out.WriteString(`<header class="hero">` + "\n")
	out.WriteString(`  <div class="hero-copy">` + "\n")
	fmt.Fprintf(&out, `    <p class="eyebrow">%s</p>`+"\n", html.EscapeString(s.Hero.Eyebrow.For(lang)))
	fmt.Fprintf(&out, `    <h1>%s</h1>`+"\n", html.EscapeString(s.Hero.Title.For(lang)))
	fmt.Fprintf(&out, `    <p class="promise">%s</p>`+"\n", s.inlineHTML(s.Hero.Promise.For(lang), lang))
	fmt.Fprintf(&out, `    <p class="lede">%s</p>`+"\n", s.inlineHTML(s.Hero.Lede.For(lang), lang))
	fmt.Fprintf(&out, `    <p class="hero-actions"><a class="button" href="%s">%s</a><a class="text-link" href="%s">%s</a></p>`+"\n",
		htmlHref(links["install"]), html.EscapeString(s.Install.Title.For(lang)), htmlHref(links["first_run"]), html.EscapeString(s.Install.FirstRun.For(lang)))
	fmt.Fprintf(&out, `    <p class="hero-note">%s</p>`+"\n", s.inlineHTML(s.Hero.Note.For(lang), lang))
	out.WriteString("  </div>\n")
	out.WriteString(`  <figure class="hero-art">` + "\n")
	fmt.Fprintf(&out, `    <img src="%s" width="640" height="480" alt="%s">`+"\n",
		s.docAsset("queue", lang), html.EscapeString(s.Hero.FigureAlt.For(lang)))
	fmt.Fprintf(&out, `    <figcaption>%s</figcaption>`+"\n", s.inlineHTML(s.Hero.FigureCaption.For(lang), lang))
	out.WriteString("  </figure>\n")
	out.WriteString("</header>\n\n")

	out.WriteString(s.navLine(lang, "index"))
	out.WriteString("\n\n")

	out.WriteString(`<section class="ask" aria-labelledby="ask-title">` + "\n")
	fmt.Fprintf(&out, `  <h2 id="ask-title">%s</h2>`+"\n", html.EscapeString(s.Ask.Title.For(lang)))
	fmt.Fprintf(&out, `  <p class="section-lead">%s</p>`+"\n", s.inlineHTML(s.Ask.Lead.For(lang), lang))
	out.WriteString(`  <ol class="ask-list">` + "\n")
	for _, mechanism := range s.Ask.Items {
		out.WriteString("    <li>\n")
		fmt.Fprintf(&out, `      <p class="card-tag">%s</p>`+"\n", html.EscapeString(mechanism.Tag.For(lang)))
		fmt.Fprintf(&out, `      <h3>%s</h3>`+"\n", html.EscapeString(mechanism.Title.For(lang)))
		fmt.Fprintf(&out, `      <p>%s</p>`+"\n", s.inlineHTML(mechanism.Body.For(lang), lang))
		out.WriteString("    </li>\n")
	}
	out.WriteString("  </ol>\n")
	fmt.Fprintf(&out, `  <p class="note">%s</p>`+"\n", s.inlineHTML(s.Ask.Note.For(lang), lang))
	fmt.Fprintf(&out, `  <p><a class="text-link" href="%s">%s</a></p>`+"\n",
		htmlHref(links["ask"]), html.EscapeString(s.Ask.Guide.For(lang)))
	out.WriteString("</section>\n\n")

	out.WriteString(`<section class="differences" aria-labelledby="differences-title">` + "\n")
	fmt.Fprintf(&out, `  <h2 id="differences-title">%s</h2>`+"\n", html.EscapeString(s.Differences.Title.For(lang)))
	fmt.Fprintf(&out, `  <p class="section-lead">%s</p>`+"\n", s.inlineHTML(s.Differences.Lead.For(lang), lang))
	out.WriteString(`  <div class="cards">` + "\n")
	for index, difference := range s.Differences.Items {
		out.WriteString(`    <article class="card">` + "\n")
		fmt.Fprintf(&out, `      <p class="card-tag">%02d / %s</p>`+"\n", index+1, html.EscapeString(difference.Tag.For(lang)))
		fmt.Fprintf(&out, `      <h3>%s</h3>`+"\n", html.EscapeString(difference.Title.For(lang)))
		fmt.Fprintf(&out, `      <p>%s</p>`+"\n", s.inlineHTML(difference.Body.For(lang), lang))
		out.WriteString("    </article>\n")
	}
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	out.WriteString(`<section class="shots" aria-labelledby="shots-title">` + "\n")
	fmt.Fprintf(&out, `  <h2 id="shots-title">%s</h2>`+"\n", html.EscapeString(s.Media.Title.For(lang)))
	fmt.Fprintf(&out, `  <p class="section-lead">%s</p>`+"\n", s.inlineHTML(s.Media.Lead.For(lang), lang))
	out.WriteString(`  <div class="shot-grid">` + "\n")
	for index, shot := range s.Media.Screenshots {
		out.WriteString(`    <figure class="shot">` + "\n")
		// Only the first image is above the fold: it loads with the page, and
		// every later capture waits until the reader scrolls to it.
		loading := "lazy"
		if index == 0 {
			loading = "eager"
		}
		fmt.Fprintf(&out, `      <img src="%s" width="%d" height="%d" loading="%s" decoding="async" alt="%s">`+"\n",
			html.EscapeString(s.mediaAsset(lang, s.ScreenshotPath(shot.Key, lang))),
			s.Media.ScreenshotWidth, s.Media.ScreenshotHeight, loading,
			html.EscapeString(s.Product+": "+shot.Title.For(lang)))
		fmt.Fprintf(&out, `      <figcaption><strong>%s</strong> %s</figcaption>`+"\n",
			html.EscapeString(shot.Title.For(lang)), s.inlineHTML(shot.Caption.For(lang), lang))
		out.WriteString("    </figure>\n")
	}
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	out.WriteString(`<section class="boundary" aria-labelledby="boundary-title">` + "\n")
	fmt.Fprintf(&out, `  <h2 id="boundary-title">%s</h2>`+"\n", html.EscapeString(s.Boundary.Title.For(lang)))
	fmt.Fprintf(&out, `  <p class="section-lead">%s</p>`+"\n", s.inlineHTML(s.Boundary.Lead.For(lang), lang))
	out.WriteString(`  <div class="boundary-grid">` + "\n")
	fmt.Fprintf(&out, `    <div class="boundary-col leaves"><h3>%s</h3><ul>`+"\n", html.EscapeString(s.Boundary.LeavesTitle.For(lang)))
	for _, entry := range s.Boundary.Leaves {
		fmt.Fprintf(&out, `      <li>%s</li>`+"\n", s.inlineHTML(entry.For(lang), lang))
	}
	out.WriteString("    </ul></div>\n")
	fmt.Fprintf(&out, `    <div class="boundary-col stays"><h3>%s</h3><ul>`+"\n", html.EscapeString(s.Boundary.StaysTitle.For(lang)))
	for _, entry := range s.Boundary.Stays {
		fmt.Fprintf(&out, `      <li>%s</li>`+"\n", s.inlineHTML(entry.For(lang), lang))
	}
	out.WriteString("    </ul></div>\n")
	out.WriteString("  </div>\n")
	fmt.Fprintf(&out, `  <p class="note">%s</p>`+"\n", s.inlineHTML(s.Boundary.Note.For(lang), lang))
	out.WriteString("</section>\n\n")

	out.WriteString(`<section class="limits" aria-labelledby="limits-title">` + "\n")
	fmt.Fprintf(&out, `  <h2 id="limits-title">%s</h2>`+"\n", html.EscapeString(s.Limits.Title.For(lang)))
	fmt.Fprintf(&out, `  <p class="section-lead">%s</p>`+"\n", s.inlineHTML(s.Limits.Lead.For(lang), lang))
	out.WriteString(`  <ol class="limit-list">` + "\n")
	for _, limit := range s.Limits.Items {
		out.WriteString("    <li>\n")
		fmt.Fprintf(&out, `      <h3>%s</h3>`+"\n", html.EscapeString(limit.Title.For(lang)))
		fmt.Fprintf(&out, `      <p>%s</p>`+"\n", s.inlineHTML(limit.Body.For(lang), lang))
		out.WriteString("    </li>\n")
	}
	out.WriteString("  </ol>\n")
	out.WriteString("</section>\n\n")

	out.WriteString(`<section class="install" id="install" aria-labelledby="install-title">` + "\n")
	out.WriteString(`  <div class="install-copy">` + "\n")
	fmt.Fprintf(&out, `    <h2 id="install-title">%s</h2>`+"\n", html.EscapeString(s.Install.Title.For(lang)))
	fmt.Fprintf(&out, `    <p class="section-lead">%s</p>`+"\n", s.inlineHTML(s.Install.Lead.For(lang), lang))
	fmt.Fprintf(&out, `    <h3>Windows</h3><p>%s</p>`+"\n", s.inlineHTML(s.Install.Windows.For(lang), lang))
	out.WriteString("  </div>\n")
	out.WriteString(`  <div class="install-panel">` + "\n")
	fmt.Fprintf(&out, `    <p class="panel-label">%s</p>`+"\n", html.EscapeString(s.Install.Panel.For(lang)))
	fmt.Fprintf(&out, `    <pre><code>%s</code></pre>`+"\n", html.EscapeString(s.Install.File))
	fmt.Fprintf(&out, `    <p class="note">%s</p>`+"\n", s.inlineHTML(s.Install.FileNote.For(lang), lang))
	fmt.Fprintf(&out, `    <a class="button button-light" href="%s">%s</a>`+"\n", htmlHref(links["first_run"]), html.EscapeString(s.Install.FirstRun.For(lang)))
	out.WriteString("  </div>\n")
	out.WriteString("</section>\n\n")

	fmt.Fprintf(&out, `<p class="install-note">%s</p>`+"\n\n", s.inlineHTML(s.Install.Note.For(lang), lang))

	out.WriteString(`<section class="status" aria-labelledby="status-title">` + "\n")
	fmt.Fprintf(&out, `  <h2 id="status-title">%s</h2>`+"\n", html.EscapeString(s.Status.Title.For(lang)))
	fmt.Fprintf(&out, `  <p>%s</p>`+"\n", s.inlineHTML(s.Status.Body.For(lang), lang))
	out.WriteString("</section>\n\n")

	out.WriteString(`<footer class="page-footer">` + "\n")
	fmt.Fprintf(&out, `  <p><strong>%s</strong> · <a href="%s">%s</a> · <a href="%s/LICENSE">%s</a> · <a href="%s">%s</a></p>`+"\n",
		html.EscapeString(s.Product), html.EscapeString(s.Repository), html.EscapeString(s.sourceLabel(lang)),
		html.EscapeString(s.Repository), LicenseID, html.EscapeString(s.docsHome(lang)), html.EscapeString(s.docsLabel(lang)))
	fmt.Fprintf(&out, `  <p><a href="%s">%s</a> · %s</p>`+"\n",
		htmlHref(links["privacy"]), html.EscapeString(s.privacyLabel(lang)), html.EscapeString(s.Hero.Banner.For(lang)))
	out.WriteString("</footer>\n")
	return []byte(out.String())
}

// Readme renders README.md or README.fr.md as the repository front door.
func (s Site) Readme(lang string) []byte {
	links := s.readmeLinks(lang)
	readmeText := func(value string) string { return s.textFor(value, lang, links) }
	var out strings.Builder
	out.WriteString(generatedHeader)
	out.WriteString("\n\n")
	fmt.Fprintf(&out, "# %s\n\n", s.Product)
	paragraph(&out, "**"+s.Hero.Promise.For(lang)+"**")
	paragraph(&out, s.Hero.Lede.For(lang))
	fmt.Fprintf(&out, "![%s](%s)\n\n", s.bannerAlt(lang), s.readmeAsset("banner", lang))
	out.WriteString(s.readmeNav(lang))
	out.WriteString("\n\n")

	heading(&out, s.Ask.Title.For(lang))
	paragraph(&out, readmeText(s.Ask.Lead.For(lang)))
	for _, example := range s.Ask.Examples {
		text := fmt.Sprintf("**%s** %s", example.Question.For(lang), readmeText(example.Body.For(lang)))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")
	paragraph(&out, readmeText(s.Ask.Guarantee.For(lang)))
	paragraph(&out, readmeText(s.Ask.Note.For(lang)))
	fmt.Fprintf(&out, "[%s](%s)\n\n", s.Ask.Guide.For(lang), links["ask"])

	heading(&out, s.Differences.Title.For(lang))
	for _, difference := range s.Differences.Items {
		text := fmt.Sprintf("**%s** %s", difference.Title.For(lang), readmeText(difference.Body.For(lang)))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Boundary.Title.For(lang))
	paragraph(&out, readmeText(s.Boundary.Lead.For(lang)))
	fmt.Fprintf(&out, "**%s**\n\n", s.Boundary.LeavesTitle.For(lang))
	for _, entry := range s.Boundary.Leaves {
		out.WriteString(item("- ", readmeText(entry.For(lang)), 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")
	fmt.Fprintf(&out, "**%s**\n\n", s.Boundary.StaysTitle.For(lang))
	for _, entry := range s.Boundary.Stays {
		out.WriteString(item("- ", readmeText(entry.For(lang)), 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")
	paragraph(&out, readmeText(s.Boundary.Note.For(lang)))

	heading(&out, s.Limits.Title.For(lang))
	for _, limit := range s.Limits.Items {
		text := fmt.Sprintf("**%s** %s", limit.Title.For(lang), readmeText(limit.Body.For(lang)))
		out.WriteString(item("- ", text, 80))
		out.WriteString("\n")
	}
	out.WriteString("\n")

	heading(&out, s.Install.Title.For(lang))
	paragraph(&out, readmeText(s.Install.Lead.For(lang)))
	paragraph(&out, "**Windows.** "+readmeText(s.Install.Windows.For(lang)))
	out.WriteString("```text\n")
	out.WriteString(s.Install.File)
	out.WriteString("\n```\n\n")
	paragraph(&out, readmeText(s.Install.FileNote.For(lang)))
	fmt.Fprintf(&out, "[%s](%s)\n\n", s.Install.FirstRun.For(lang), links["first_run"])

	heading(&out, s.Status.Title.For(lang))
	paragraph(&out, readmeText(s.Status.Body.For(lang)))

	heading(&out, s.Build.Title.For(lang))
	paragraph(&out, readmeText(s.Build.Requirements.For(lang)))
	out.WriteString("```bash\n")
	out.WriteString(strings.TrimRight(s.Build.Commands, "\n"))
	out.WriteString("\n```\n\n")
	paragraph(&out, readmeText(s.Build.Note.For(lang)))

	heading(&out, s.License.Title.For(lang))
	paragraph(&out, readmeText(s.License.Body.For(lang)))

	fmt.Fprintf(&out, "[%s](%s)\n", s.docsLabel(lang), s.docsHome(lang))
	return []byte(strings.TrimRight(out.String(), "\n") + "\n")
}

// readmeNav is the language switch, the documentation home, the public
// destinations and the published site.
func (s Site) readmeNav(lang string) string {
	links := s.readmeLinks(lang)
	docs := "docs/index.md"
	if lang == "fr" {
		docs = "docs/fr/index.md"
	}
	parts := []string{languageSwitch(lang), fmt.Sprintf("[%s](%s)", s.docsLabel(lang), docs)}
	for _, item := range s.Nav {
		href, ok := links[item.Key]
		if !ok {
			continue
		}
		parts = append(parts, fmt.Sprintf("[%s](%s)", item.Label.For(lang), href))
	}
	parts = append(parts, fmt.Sprintf("[%s](%s)", s.siteLabel(lang), s.docsHome(lang)))
	return strings.Join(parts, " · ")
}

func languageSwitch(lang string) string {
	if lang == "fr" {
		return "[English](README.md)"
	}
	return "[Français](README.fr.md)"
}

func (s Site) sourceLabel(lang string) string {
	if lang == "fr" {
		return "Code source"
	}
	return "Source"
}

func (s Site) siteLabel(lang string) string {
	if lang == "fr" {
		return "Site de documentation"
	}
	return "Docs site"
}

func (s Site) privacyLabel(lang string) string {
	if lang == "fr" {
		return "Confidentialité"
	}
	return "Privacy"
}

// docsHome is the published documentation home in the page's language.
func (s Site) docsHome(lang string) string {
	if lang == "fr" {
		return strings.TrimSuffix(s.DocsSite, "/") + "/fr/"
	}
	return s.DocsSite
}

// bannerAlt is the accessible description of the generated banner.
func (s Site) bannerAlt(lang string) string {
	return s.Product + ": " + s.Hero.Banner.For(lang)
}
